    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Articles were included if they were peer-reviewed articles published in English or Spanish ... that reported mental health outcomes in clinical staff managing high-risk infectious disease outbreaks. We considered studies on all healthcare staff in all settings as relevant. ... Studies of methodologies including quantitative studies, qualitative studies, and anecdotal accounts, reporting original results were included.",
      "reason": "The Methods specify eligible population (clinical/healthcare staff in high-risk infectious disease outbreaks), outcomes (mental health outcomes), settings (all settings), and study designs (quantitative, qualitative, anecdotal accounts reporting original results)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Articles were included if they were peer-reviewed articles published in English or Spanish (the languages of the authors) that reported mental health outcomes... One article in Chinese with numeric results reported in the English-language abstract was also included.",
      "reason": "Report characteristics including publication status (peer-reviewed, with pre-prints searched) and language (English or Spanish, plus one Chinese article with English abstract) are specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported; no such distinction appears in the Methods text."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "We defined high and low exposures as direct contact with infected patients, or work in wards where direct contact was considered highly likely (e.g. critical care, designated treatment wards, emergency departments) compared to clinicians working without direct contact or work in hospital areas where direct contact was unlikely. A narrative synthesis of risk factors was conducted across all studies regardless of methodology.",
      "reason": "The groups used in the syntheses (high- vs low-exposure comparisons for the meta-analyses and all studies for the narrative synthesis of risk factors) are explicitly defined and linked to the review's comparison objective."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "Articles were included if they were peer-reviewed articles published in English or Spanish (the languages of the authors)",
      "reason": "A brief rationale is given for the language restriction ('the languages of the authors'), and the rapid review approach is framed as a pragmatic choice, but rationales for other notable restrictions (e.g., pre-print searches limited to COVID-19, peer-review requirement) are not explicitly provided."
    }
  ],
  "confidence": 88
}

